using System.Windows;using System.Windows.Controls;using Microsoft.Win32;using FacialPresets;
namespace FacialStudio;
public sealed class TransitionDialog:Window {
 sealed record Choice(Preset Preset){public override string ToString()=>Preset.Name;}
 public FacialClip? Result{get;private set;}
 public static FacialClip Create(Preset start,Preset end,double seconds){PresetFile.Validate(start);PresetFile.Validate(end);if(!double.IsFinite(seconds)||seconds<=0||seconds>600)throw new System.IO.InvalidDataException(L.T("전환 길이는 0초 초과 600초 이하여야 합니다."));var c=new FacialClip{Name=start.Name+" → "+end.Name,Profile=start.Profile,Duration=seconds,RequiredResources=start.RequiredResources.Concat(end.RequiredResources).Distinct().ToList(),Keys=[new(){Time=0,State=FacialTimeline.Copy(start)},new(){Time=seconds,State=FacialTimeline.Copy(end)}]};FacialClipFile.Validate(c);return c;}
 public TransitionDialog(IEnumerable<Preset> opened){Title=L.T("표정 전환 만들기");Width=530;Height=365;WindowStartupLocation=WindowStartupLocation.CenterOwner;DanceStudio.StudioTheme.Window(this);var root=new StackPanel{Margin=new Thickness(16)};Content=root;var choices=opened.Select(p=>new Choice(FacialTimeline.Copy(p))).ToList();var from=new ComboBox{ItemsSource=choices,SelectedIndex=choices.Count>0?0:-1};var to=new ComboBox{ItemsSource=choices.ToList(),SelectedIndex=choices.Count>1?1:choices.Count>0?0:-1};void Source(string title,ComboBox box){root.Children.Add(new TextBlock{Text=L.T(title),Foreground=DanceStudio.StudioTheme.Text});var row=new DockPanel();root.Children.Add(row);var b=new Button{Content=L.T("파일에서 선택")};DockPanel.SetDock(b,Dock.Right);row.Children.Add(b);row.Children.Add(box);b.Click+=(_,_)=>{var d=new OpenFileDialog{Filter="Facial preset|*.facialpreset.json"};if(d.ShowDialog(this)==true)try{var p=new Choice(PresetFile.Load(d.FileName));box.ItemsSource=box.Items.Cast<Choice>().Append(p).ToList();box.SelectedItem=p;}catch(Exception e){MessageBox.Show(this,L.T(e.Message));}};}
  Source("시작 프리셋",from);Source("종료 프리셋",to);root.Children.Add(new TextBlock{Text=L.T("전환 길이(초)"),Foreground=DanceStudio.StudioTheme.Text});var duration=new TextBox{Text="0.5"};root.Children.Add(duration);root.Children.Add(new TextBlock{Text=L.T("생성 후 재생 버튼으로 미리보고 클립 저장을 누르세요."),Foreground=DanceStudio.StudioTheme.Muted,TextWrapping=TextWrapping.Wrap});root.Children.Add(new TextBlock{Text=L.T("MFG 감정 전환은 중립을 거칩니다. 모프 지원은 얼굴 리소스에 따라 다릅니다."),TextWrapping=TextWrapping.Wrap,Foreground=DanceStudio.StudioTheme.Muted});var create=new Button{Content=L.T("전환 만들기")};root.Children.Add(create);create.Click+=(_,_)=>{try{if(from.SelectedItem is not Choice a||to.SelectedItem is not Choice b)throw new InvalidOperationException(L.T("시작과 종료 프리셋을 선택하세요."));Result=Create(a.Preset,b.Preset,double.Parse(duration.Text,System.Globalization.CultureInfo.InvariantCulture));DialogResult=true;}catch(Exception e){MessageBox.Show(this,L.T(e.Message));}};
 }
}
